function factorial(n) {
    let result = 1;
    for (let i = 2; i <= n; i++) { result *= i; }
    return result;
}

function sumOfDigitsFactorials(num) {
    const digits = Array.from(String(num)).map(n => parseInt(n))
    let total = 0

    for (let i = 0; i < digits.length; i++) {
        total += factorial(digits[i]);
    }

    return total;
}

function findMagicNumber() {
    for (let num = 100; num <= 999; num++) {
        if (num < 10 && num > 0) {
            if (sumOfDigitsFactorials(num) === num) {
                console.log(num, num * 10); // Verify it meets the criteria
                return num;
            }
        }
    }
}

findMagicNumber();
